@Serializable
sealed interface Event

@Serializable @SerialName("login")
data class Login(val userId: String) : Event

@Serializable @SerialName("logout")
object Logout : Event

val text = Json.encodeToString<Event>(Login("u1"))   // {"type":"login","userId":"u1"}
